-- =============================================================================
-- PRISMO — TABEL SUPABASE: inisiatif_ak_dosen
-- Data diekstrak dari Google Spreadsheet Rekap Publikasi LAN (9 Sheet Unit Kerja)
-- Total Records: 700
-- =============================================================================

CREATE TABLE IF NOT EXISTS public.inisiatif_ak_dosen (
    id BIGSERIAL PRIMARY KEY,
    no INT,
    unit TEXT NOT NULL,
    source_sheet TEXT NOT NULL,
    judul TEXT NOT NULL,
    jenis TEXT DEFAULT '',
    jadwal_publikasi TEXT DEFAULT '',
    tahun INT,
    cluster_1 TEXT DEFAULT '',
    cluster_2 TEXT DEFAULT '',
    jurnal TEXT DEFAULT '',
    media_online TEXT DEFAULT '',
    website_lan TEXT DEFAULT '',
    website_unit TEXT DEFAULT '',
    instagram_lan TEXT DEFAULT '',
    instagram_unit TEXT DEFAULT '',
    youtube_lan TEXT DEFAULT '',
    youtube_unit TEXT DEFAULT '',
    media_televisi TEXT DEFAULT '',
    catatan TEXT DEFAULT '',
    created_at TIMESTAMPTZ DEFAULT NOW(),
    updated_at TIMESTAMPTZ DEFAULT NOW()
);

-- Index untuk performa query
CREATE INDEX IF NOT EXISTS idx_inisiatif_ak_dosen_unit ON public.inisiatif_ak_dosen (unit);
CREATE INDEX IF NOT EXISTS idx_inisiatif_ak_dosen_tahun ON public.inisiatif_ak_dosen (tahun);

-- Aktifkan Row Level Security (RLS)
ALTER TABLE public.inisiatif_ak_dosen ENABLE ROW LEVEL SECURITY;

-- Policies
DO $$
BEGIN
    DROP POLICY IF EXISTS "Inisiatif Public Read" ON public.inisiatif_ak_dosen;
    DROP POLICY IF EXISTS "Inisiatif Public Insert" ON public.inisiatif_ak_dosen;
    DROP POLICY IF EXISTS "Inisiatif Public Update" ON public.inisiatif_ak_dosen;
    DROP POLICY IF EXISTS "Inisiatif Public Delete" ON public.inisiatif_ak_dosen;
END $$;

CREATE POLICY "Inisiatif Public Read" ON public.inisiatif_ak_dosen FOR SELECT USING (true);
CREATE POLICY "Inisiatif Public Insert" ON public.inisiatif_ak_dosen FOR INSERT WITH CHECK (true);
CREATE POLICY "Inisiatif Public Update" ON public.inisiatif_ak_dosen FOR UPDATE USING (true);
CREATE POLICY "Inisiatif Public Delete" ON public.inisiatif_ak_dosen FOR DELETE USING (true);

-- Hapus unique constraint lama jika ada agar tidak bentrok
ALTER TABLE IF EXISTS public.inisiatif_ak_dosen DROP CONSTRAINT IF EXISTS inisiatif_ak_dosen_source_sheet_no_key;
DROP INDEX IF EXISTS public.inisiatif_ak_dosen_source_sheet_no_key;

-- Bersihkan data lama terlebih dahulu agar aman dijalankan berulang kali (Idempotent)
TRUNCATE TABLE public.inisiatif_ak_dosen RESTART IDENTITY;

